(function(){
  var nav = document.querySelector('.nav');
  var toggle = document.getElementById('navToggle');
  if (!nav || !toggle) return;
  toggle.addEventListener('click', function(){
    var open = nav.classList.toggle('open');
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  });
  nav.querySelectorAll('.nav-links a').forEach(function(a){
    a.addEventListener('click', function(){
      nav.classList.remove('open');
      toggle.setAttribute('aria-expanded', 'false');
    });
  });
})();

(function(){
  var els = document.querySelectorAll('.subpage .reveal');
  if (!els.length) return;
  function cascade(el){
    var tiles = el.querySelectorAll('.t');
    tiles.forEach(function(t, i){ setTimeout(function(){ t.classList.add('show'); }, i * 80); });
  }
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduce || !('IntersectionObserver' in window)){
    els.forEach(function(el){ el.classList.add('in'); el.querySelectorAll('.t').forEach(function(t){ t.classList.add('show'); }); });
    return;
  }
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){ e.target.classList.add('in'); cascade(e.target); io.unobserve(e.target); }
    });
  }, { threshold:.12, rootMargin:'0px 0px -8% 0px' });
  els.forEach(function(el){ io.observe(el); });
})();

