/* logo colour adapts to the section behind it (white on dark, orange on light) */
(function(){
  var logo = document.querySelector('.site-logo');
  if (!logo || !('IntersectionObserver' in window)) return;
  var darks = [];
  ['.hero', '.cta-section', '.footer'].forEach(function(sel){
    document.querySelectorAll(sel).forEach(function(el){ darks.push(el); });
  });
  if (!darks.length) return;
  var active = new Set();
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){ if (e.isIntersecting) active.add(e.target); else active.delete(e.target); });
    logo.classList.toggle('on-dark', active.size > 0);
  }, { rootMargin:'-44px 0px -92% 0px', threshold:0 });
  darks.forEach(function(el){ io.observe(el); });
})();

/* ---- footer: decoding/scramble effect when it scrolls into view (matches home) ---- */
(function(){
  var footer = document.querySelector('.footer');
  if (!footer) return;
  var targets = footer.querySelectorAll('h3, h4, .f-tag');
  var CH = '!<>-_\\/[]{}=+*^?#@%$&';
  function decode(el, delay){
    if (el._dec) return;
    el._dec = true;
    var finalText = el.getAttribute('data-text') || el.textContent;
    el.setAttribute('data-text', finalText);
    var queue = [], frame = 0;
    for (var i = 0; i < finalText.length; i++){
      var c = finalText[i];
      if (c === ' '){ queue.push({to:' ', start:0, end:0}); continue; }
      var start = delay + Math.floor(Math.random() * 16);
      var end = start + 14 + Math.floor(Math.random() * 24);
      queue.push({to:c, start:start, end:end, ch:''});
    }
    (function run(){
      var out = '', done = 0;
      for (var i = 0; i < queue.length; i++){
        var q = queue[i];
        if (frame >= q.end){ done++; out += q.to; }
        else if (frame >= q.start){
          if (!q.ch || Math.random() < 0.3) q.ch = CH[Math.floor(Math.random() * CH.length)];
          out += '<span class="dec">' + q.ch + '</span>';
        }
      }
      el.innerHTML = out;
      frame++;
      if (done < queue.length) requestAnimationFrame(run);
      else { el.textContent = finalText; el._dec = false; }
    })();
  }
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduce) return;
  footer.querySelectorAll('a, h3, h4, .f-tag').forEach(function(el){
    el.addEventListener('mouseenter', function(){ decode(el, 0); });
  });
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){ targets.forEach(function(el, i){ decode(el, i * 5); }); io.disconnect(); }
    });
  }, { threshold:0.2 });
  io.observe(footer);
})();

/* ---- nav: hide on scroll down, show on scroll up (matches home) ---- */
(function(){
  var nav = document.querySelector('.nav');
  if (!nav) return;
  var last = window.pageYOffset || 0, ticking = false;
  function onScroll(){
    ticking = false;
    var y = window.pageYOffset || document.documentElement.scrollTop || 0;
    if (nav.classList.contains('open')){ document.body.classList.remove('nav-up'); last = y; return; }
    if (y > last && y > 140){ document.body.classList.add('nav-up'); }
    else { document.body.classList.remove('nav-up'); }
    last = y < 0 ? 0 : y;
  }
  window.addEventListener('scroll', function(){ if (!ticking){ ticking = true; requestAnimationFrame(onScroll); } }, { passive:true });
})();
